_TOML_BEGIN, _TOML_END = f"# >>> {MARK}", f"# <<< {MARK}"


def _kimi(repo: Path, url: str) -> Path:
    home = Path(os.environ["KIMI_CODE_HOME"]) if os.environ.get("KIMI_CODE_HOME") else Path.home() / ".kimi-code"
    path = home / "config.toml"
    text = path.read_text(encoding="utf-8") if path.exists() else ""
    text = re.sub(rf"\n*{re.escape(_TOML_BEGIN)}.*?{re.escape(_TOML_END)}\n?", "\n", text, flags=re.S).strip()
    # TOML literal strings: no escapes, and _safe_path already refuses a single quote.
    rules = [f"[[hooks]]\nevent = \"{e}\"\ncommand = '{_command(repo, 'kimi', e)}'\ntimeout = {150 if e == 'Stop' else 30}\n"
             for e in ("UserPromptSubmit", "PreToolUse", "PostToolUse", "PostToolUseFailure", "Stop")]
    block = _TOML_BEGIN + "\n" + "\n".join(rules) + _TOML_END + "\n"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text((text + "\n\n" if text else "") + block, encoding="utf-8")
    return path


