AMP_PLUGIN = """// solo-license: earned autonomy for Amp
import type { PluginAPI } from "@ampcode/plugin"

export const description = "Solo License: answers tool calls from what this repo has earned"

const BASE: string = process.env.SOLO_LICENSE_URL ?? __URL__

async function gate(event: string, body: unknown): Promise<any> {
  try {
    const r = await fetch(`${BASE}/api/hooks/amp/${event}`, {
      method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body),
    })
    return await r.json()
  } catch {
    return {} // Solo License is down: Amp behaves as if it were not installed
  }
}

export default function (amp: PluginAPI) {
  amp.on("agent.start", async (event: any) => {
    await gate("agent.start", { thread_id: event.thread?.id, prompt: event.message, cwd: process.cwd() })
    return {}
  })
  amp.on("tool.call", async (event: any) => {
    const d = await gate("tool.call", { thread_id: event.thread?.id, tool_name: event.tool, tool_input: event.input, cwd: process.cwd() })
    if (d?.action === "reject-and-continue") return { action: "reject-and-continue", message: d.message ?? "Blocked by Solo License" }
    return { action: "allow" }
  })
  amp.on("tool.result", async (event: any) => {
    await gate("tool.result", { thread_id: event.thread?.id, tool_name: event.tool, tool_input: event.input, status: event.status, error: event.error, cwd: process.cwd() })
  })
  amp.on("agent.end", async (event: any) => {
    const d = await gate("agent.end", { thread_id: event.thread?.id, status: event.status, cwd: process.cwd() })
    if (d?.action === "continue" && d.userMessage) return { action: "continue", userMessage: d.userMessage }
  })
}
"""


