def _auggie(repo: Path, url: str) -> Path:
    """Auggie runs only .sh / .cmd / .ps1 / .bat files, so each event gets a tiny script."""
    folder = repo / ".solo-license" / "auggie"
    folder.mkdir(parents=True, exist_ok=True)
    python, hook = _paths(repo)
    windows = os.name == "nt"

    def script(event: str) -> str:
        if windows:
            target = folder / f"{event}.cmd"
            target.write_text(f'@echo off\r\nrem {MARK}\r\n"{python}" "{hook}" auggie {event}\r\n'
                              "exit /b %ERRORLEVEL%\r\n", encoding="utf-8")
        else:
            target = folder / f"{event}.sh"
            target.write_text(f"#!/bin/sh\n# {MARK}\nexec {shlex.quote(python)} {shlex.quote(hook)} auggie {event}\n",
                              encoding="utf-8")
            target.chmod(target.stat().st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
        return _safe_path(str(target), "repository")

    def entry(event: str, timeout: int = 30000, matcher: bool = True) -> dict:
        return {**({"matcher": ".*"} if matcher else {}),
                "hooks": [{"type": "command", "command": script(event), "timeout": timeout}],
                "metadata": {"includeUserContext": True}}

    ours = {"PreToolUse": [entry("PreToolUse")], "PostToolUse": [entry("PostToolUse")],
            "Stop": [entry("Stop", 150000, matcher=False)]}
    path = repo / ".augment" / "settings.local.json"
    data = _load(path)
    data["hooks"] = _merge(data.get("hooks", {}), ours)
    _save(path, data)
    return path


