    cmd = lambda e, t=30: {"type": "command", "command": _command(repo, "goose", e), "timeout": t}  # noqa: E731
    path = plugin / "hooks" / "hooks.json"
    _save(path, {"hooks": {e: [{"hooks": [cmd(e, 150 if e == "Stop" else 30)]}]
                           for e in ("UserPromptSubmit", "PreToolUse", "PostToolUse", "PostToolUseFailure", "Stop")}})
    return path


def _junie(repo: Path, url: str) -> Path:
