css="""
/* ---------- hero: the gate feed ---------- */
.lp-feed { position: absolute !important; left: 6%; right: 6%; bottom: 6%; top: 18%; background: var(--sheet); padding: 16px 18px 14px; z-index: 2; display: flex; flex-direction: column; gap: 10px; overflow: hidden; }
.lp-feed > * { position: relative; z-index: 1; }
.lp-feed-top { display: flex; justify-content: space-between; gap: 12px; padding-bottom: 10px; border-bottom: 1px solid var(--hair); font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; }
.lp-feed-rows { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; flex: 1; min-height: 0; justify-content: flex-end; }
.lp-feed-row { display: grid; grid-template-columns: 1fr auto; gap: 2px 10px; padding: 8px 10px; border: 1px solid var(--hair); background: var(--paper); }
.lp-feed-cmd { font: 500 13px/1.35 var(--font-mono); overflow-wrap: anywhere; }
.lp-feed-why { grid-column: 1 / -1; color: var(--muted); font-size: 12px; line-height: 1.35; }
.lp-feed-verdict { align-self: start; font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; padding: 2px 8px; border: 1px solid var(--ink); white-space: nowrap; }
.lp-feed-verdict.is-allow { background: var(--ink); color: var(--paper); }
.lp-feed-verdict.is-ask { background: var(--sheet); }
.lp-feed-verdict.is-deny, .lp-feed-verdict.is-back { background: var(--paper); text-decoration: underline; text-decoration-thickness: 2px; }
.lp-feed-row.is-deny, .lp-feed-row.is-back { border-color: var(--ink); }
.lp-feed-levels { display: grid; grid-template-columns: repeat(4, 1fr); border-top: 1px solid var(--hair); border-bottom: 1px solid var(--hair); }
.lp-feed-level { padding: 8px 8px 6px; display: grid; gap: 2px; transition: background 0.4s; }
.lp-feed-level + .lp-feed-level { border-left: 1px solid var(--hair); }
.lp-feed-level span.mono { font-size: 10px; text-transform: uppercase; letter-spacing: 0.05em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.lp-feed-level b { font-size: 30px; line-height: 1; font-weight: 400; }
.lp-feed-level.is-moved { background: var(--paper); }
.lp-feed-rungs { display: flex; gap: 3px; }
.lp-feed-rungs i { width: 14px; height: 5px; border: 1px solid var(--ink); }
.lp-feed-rungs i.on { background: var(--ink); }
.lp-feed-proof { display: flex; flex-wrap: wrap; gap: 6px 14px; font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.05em; }
@media (max-width: 560px) {
  .lp-feed { left: 4%; right: 4%; top: 6%; bottom: 4%; padding: 12px; }
  .lp-feed-levels { grid-template-columns: repeat(2, 1fr); }
  .lp-feed-level:nth-child(3) { border-left: 0; }
  .lp-feed-level:nth-child(n+3) { border-top: 1px solid var(--hair); }
}
@media (min-width: 901px) and (max-height: 820px) {
  .lp-feed { top: 14%; }
  .lp-feed-why { display: none; }
}
"""
open("landing.css","a",encoding="utf-8",newline="").write(css)
